-- Inspect current search path
SHOW search_path;

-- Create dedicated tenant schema
CREATE SCHEMA tenant_acme;
CREATE TABLE tenant_acme.invoices (id SERIAL PRIMARY KEY, total NUMERIC);

-- Set session path to prioritize tenant
SET search_path TO tenant_acme, public;

-- Resolves to tenant_acme.invoices automatically!
SELECT * FROM invoices;

-- Create a schema and let the current role use it
CREATE SCHEMA reporting AUTHORIZATION app_admin;

-- USAGE lets you see/resolve objects; CREATE lets you add new ones
GRANT USAGE ON SCHEMA reporting TO analyst;
GRANT CREATE ON SCHEMA reporting TO app_admin;

-- $user resolves to the session user's own schema, if it exists
SET search_path TO "$user", app, public;
SHOW search_path;    -- "$user", app, public

-- Fully-qualified names always win regardless of search_path
SELECT count(*) FROM reporting.daily_sales;
